// Validates the Orchestrator's request, decides urgency, and builds the Telegram message.
const body = $json.body || {};
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const errors = [];

const conversationId = str(body.conversation_id);
const reason = str(body.reason).toLowerCase().replace(/\s+/g, '_');
const summary = str(body.summary).slice(0, 500);
if (!conversationId) errors.push('conversation_id is required');
if (!reason) errors.push('reason is required');
if (!summary) errors.push('summary is required');

// frustration_score comes from the Silence Decoder (1-10). Optional.
let score = null;
if (body.frustration_score !== undefined && body.frustration_score !== null && body.frustration_score !== '') {
  const n = Number(body.frustration_score);
  if (Number.isNaN(n) || n < 1 || n > 10) errors.push('frustration_score must be a number from 1 to 10');
  else score = n;
}

if (errors.length) return [{ json: { valid: false, duplicate: false, errors } }];

// ---- duplicate check (same conversation escalated again within N minutes) ----
// Note: workflow static data is only saved when the workflow is ACTIVE.
const store = $getWorkflowStaticData('global');
const last = (store.recent || {})[conversationId];
const windowMs = Number($json.dedupe_minutes || 10) * 60 * 1000;
if (last && Date.now() - last < windowMs) {
  return [{ json: { valid: true, duplicate: true, conversation_id: conversationId } }];
}

// ---- urgency rules ----
const HIGH_REASONS = ['payment_issue', 'refund_dispute'];
const MEDIUM_REASONS = ['repeated_failure', 'customer_request'];
let urgency = 'low';
if ((score !== null && score >= 8) || HIGH_REASONS.includes(reason)) urgency = 'high';
else if ((score !== null && score >= 5) || MEDIUM_REASONS.includes(reason)) urgency = 'medium';
const slaMinutes = { high: 5, medium: 15, low: 60 }[urgency];
const icon = { high: '\u{1F6A8}', medium: '\u26A0\uFE0F', low: '\u{1F4AC}' }[urgency];

// ---- message ----
const channel = str(body.channel).toLowerCase() || 'web';
const customer = body.customer && typeof body.customer === 'object' ? body.customer : {};
const maskPhone = (p) => { const d = String(p || '').replace(/\D/g, ''); return d.length >= 4 ? `***${d.slice(-4)}` : ''; };
const who = [str(customer.name), maskPhone(customer.phone)].filter(Boolean).join(' ');
const lastMessages = Array.isArray(body.last_messages)
  ? body.last_messages.filter((m) => typeof m === 'string' && m.trim()).slice(-3).map((m) => m.trim().slice(0, 200))
  : [];

const lines = [
  `${icon} ${urgency.toUpperCase()} escalation (reply within ${slaMinutes} min)`,
  `Conversation: ${conversationId}`,
  `Channel: ${channel}`,
  `Reason: ${reason}`,
];
if (score !== null) lines.push(`Frustration: ${score}/10`);
if (who) lines.push(`Customer: ${who}`);
lines.push('', 'Summary:', summary);
if (lastMessages.length) lines.push('', 'Last messages:', ...lastMessages.map((m) => `- ${m}`));

const chatId = urgency === 'high' && $json.supervisor_chat_id ? $json.supervisor_chat_id : $json.team_chat_id;
const escalationId = 'ESC-' + Date.now().toString(36).toUpperCase();

return [{ json: {
  valid: true, duplicate: false,
  escalation_id: escalationId, conversation_id: conversationId,
  urgency, sla_minutes: slaMinutes, chat_id: chatId, text: lines.join('\n'),
  send_telegram: $json.send_telegram === true || $json.send_telegram === 'true',
} }];

// Runs only AFTER Telegram succeeded, so a failed send can be retried by the caller.
const v = $('Validate & Classify').first().json;
const store = $getWorkflowStaticData('global');
store.recent = store.recent || {};
const now = Date.now();
for (const [k, t] of Object.entries(store.recent)) if (now - t > 3600 * 1000) delete store.recent[k];
store.recent[v.conversation_id] = now;
const out = { escalation_id: v.escalation_id, urgency: v.urgency, sla_minutes: v.sla_minutes };
if (!v.send_telegram) { out.dry_run = true; out.preview = v.text; }
return [{ json: out }];
